import { ReactNode, FC } from 'react';

interface DropdownOption {
    /** 选项文字 */
    text: string;
    /** 选项值 */
    value: string | number;
    /** 是否禁用 */
    disabled?: boolean;
    /** 自定义图标 */
    icon?: ReactNode;
}
interface DropdownItemProps {
    /** 当前选中值 */
    value?: string | number;
    /** 默认选中值 */
    defaultValue?: string | number;
    /** 选项列表 */
    options: DropdownOption[];
    /** 菜单标题 */
    title?: string;
    /** 是否禁用 */
    disabled?: boolean;
    /** 值变化回调 */
    onChange?: (value: string | number) => void;
    /** 自定义类名 */
    className?: string;
}
interface DropdownMenuProps {
    /** 当前展开项的 index */
    activeKey?: number | null;
    /** 默认展开项 */
    defaultActiveKey?: number | null;
    /** 展开变化回调 */
    onActiveKeyChange?: (key: number | null) => void;
    /** 选中态颜色 */
    activeColor?: string;
    /** 下拉框方向 */
    direction?: 'up' | 'down';
    /** 是否显示遮罩 */
    overlay?: boolean;
    /** 点击遮罩关闭 */
    closeOnOverlayClick?: boolean;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const DropdownMenu: FC<DropdownMenuProps>;
interface DropdownItemInternalProps extends DropdownItemProps {
    __index?: number;
}
declare const DropdownItem: FC<DropdownItemInternalProps>;
declare const Dropdown: {
    Menu: FC<DropdownMenuProps>;
    Item: FC<DropdownItemInternalProps>;
};

export { Dropdown, DropdownItem, DropdownMenu, Dropdown as default };
export type { DropdownItemProps, DropdownMenuProps, DropdownOption };
